#!/bin/sh
# Compiles cui-sys/probe/sigcheck.c (generated by scripts/gen_ffi.py): every
# Rust extern declaration, mapped back to C, is assigned to a function pointer
# and checked against cui.h. A dropped parameter, a lost pointer level, a
# changed qualifier or a missing `...` is a hard compile error.
set -eu
cd "$(dirname "$0")/.."
cc -std=c99 -fsyntax-only -Werror -I cui-sys/c cui-sys/probe/sigcheck.c
echo "sigcheck: every extern declaration matches its C prototype"
